  'Creators must provide accurate titles, descriptions, categories, languages, thumbnails, captions, visibility, and scheduling settings. Scheduled videos are not public until their scheduled time and successful processing.' => 'ผู้สร้างจะต้องระบุชื่อ คำอธิบาย หมวดหมู่ ภาษา ภาพขนาดย่อ คำบรรยาย การมองเห็น และการกำหนดเวลาที่ถูกต้อง วิดีโอที่กำหนดเวลาไว้จะไม่เปิดเผยต่อสาธารณะจนกว่าจะถึงเวลาที่กำหนดไว้และการประมวลผลสำเร็จ',
