  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'ความคืบหน้าในการเล่น สถานะดูภายหลัง การถูกใจ ความคิดเห็น การสมัครรับข้อมูล การแจ้งเตือน และการวิเคราะห์ของผู้ดูแลระบบจะถูกจัดเก็บไว้ในฐานข้อมูลเมื่อเชื่อมโยงกับฟีเจอร์แพลตฟอร์มที่ได้รับการตรวจสอบสิทธิ์',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'การเล่น ความคิดเห็น การถูกใจ ดูภายหลัง การติดตาม การแจ้งเตือน ข้อความ เพลย์ลิสต์ และการตั้งค่าภาษามีให้ใช้งานผ่านการนำทางหลักและเมนูบัญชี',
  'PlayHub' => 'เพลย์ฮับ',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub เป็นแพลตฟอร์มวิดีโอสำหรับการอัปโหลด ดู กำหนดเวลา จัดการ และกลั่นกรองเนื้อหาของผู้สร้างจากบัญชีเดียว',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub เป็นแพลตฟอร์มวิดีโอที่ทำงานในการใช้งานนี้ สร้างขึ้นสำหรับผู้สร้าง ผู้ชม ชุมชน และผู้ให้บริการแพลตฟอร์ม',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub นำเสนอช่องสำหรับผู้สร้าง การอัปโหลดวิดีโอ การเผยแพร่ตามกำหนดเวลา การติดตาม ความคิดเห็น เพลย์ลิสต์ ดูภายหลัง หน้าเนื้อหาสด และเครื่องมือการดูแลระบบจากแพลตฟอร์มเดียว',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub ใช้คุกกี้และพื้นที่เก็บข้อมูลเบราว์เซอร์ที่จำเป็นสำหรับเซสชันการเข้าสู่ระบบ การตรวจสอบสิทธิ์ API พฤติกรรม CSRF/ความปลอดภัย การเลือกภาษา การเลือกธีม สถานะเมนูบัญชี และคุณสมบัติอื่น ๆ ที่จำเป็นสำหรับแอปพลิเคชันในการทำงาน',
