  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'ความเป็นส่วนตัว คุกกี้ ความปลอดภัยของบัญชี ข้อความสนับสนุน และข้อมูลการตรวจสอบได้รับการจัดการผ่านนโยบายและบันทึกแบ็กเอนด์ที่เชื่อมต่อกับ PlayHub',
  'Profile, login, security, and settings help.' => 'ความช่วยเหลือเกี่ยวกับโปรไฟล์ การเข้าสู่ระบบ ความปลอดภัย และการตั้งค่า',
