  'Refund and paid feature guidance.' => 'คำแนะนำเกี่ยวกับฟีเจอร์การคืนเงินและการชำระเงิน',
  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'การจัดการการคืนเงินสำหรับฟีเจอร์ PlayHub แบบชำระเงินจะขึ้นอยู่กับบันทึกการเรียกเก็บเงินจริงที่แนบมากับการใช้งานนี้',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'การจัดการการคืนเงินจะเชื่อมโยงกับบันทึกการเรียกเก็บเงินจริงและการตรวจสอบของผู้ดูแลระบบ หากไม่มีการกำหนดค่าการเรียกเก็บเงินสำหรับการปรับใช้นี้ จะไม่มีการเรียกเก็บค่าธรรมเนียมแพลตฟอร์มในการคืนเงิน',
  'Refund issued' => 'ออกเงินคืนแล้ว',
