  'sample endpoints loaded' => 'โหลดปลายทางตัวอย่างแล้ว',
  'Schedule video' => 'กำหนดเวลาวิดีโอ',
  'Scheduled video release and reminders.' => 'การเปิดตัววิดีโอตามกำหนดการและการแจ้งเตือน',
  'Scheduled videos' => 'วิดีโอตามกำหนดเวลา',
  'Scheduling a video release' => 'กำหนดการเผยแพร่วิดีโอ',
  'Search for answers...' => 'ค้นหาคำตอบ...',
  'Search help articles, topics, or questions...' => 'ค้นหาบทความช่วยเหลือ หัวข้อ หรือคำถาม...',
  'Select a reason' => 'เลือกเหตุผล',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'เลือกไฟล์วิดีโออย่างน้อยหนึ่งไฟล์ ป้อนรายละเอียดที่จำเป็น เลือกหมวดหมู่และภาษา เพิ่มภาพขนาดย่อ เลือกการเปิดเผย และเผยแพร่ ไฟล์ขนาดใหญ่จะถูกอัปโหลดเป็นกลุ่มก่อนที่เซิร์ฟเวอร์จะเริ่มประมวลผล',
  'Send a message and it will be saved for admins.' => 'ส่งข้อความและมันจะถูกบันทึกไว้สำหรับผู้ดูแลระบบ',
  'Send billing details to admin support for review.' => 'ส่งรายละเอียดการเรียกเก็บเงินไปยังฝ่ายสนับสนุนผู้ดูแลระบบเพื่อตรวจสอบ',
  'Send message' => 'ส่งข้อความ',
  'Send order details through the refund popup.' => 'ส่งรายละเอียดคำสั่งซื้อผ่านป๊อปอัปการคืนเงิน',
  'Send us a message' => 'ส่งข้อความถึงเรา',
  'Sending...' => 'กำลังส่ง...',
  'Server configured' => 'กำหนดค่าเซิร์ฟเวอร์แล้ว',
  'server records' => 'บันทึกเซิร์ฟเวอร์',
  'Service operation' => 'การดำเนินงานบริการ',
  'session, token' => 'เซสชันโทเค็น',
  'Settings and login' => 'การตั้งค่าและการเข้าสู่ระบบ',
  'Short summary' => 'สรุปสั้นๆ',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'ลงชื่อเข้าใช้และใช้การตั้งค่าสำหรับบัญชี โปรไฟล์ รหัสผ่าน การแจ้งเตือน ความเป็นส่วนตัว และการตั้งค่าผู้สร้าง ปัญหาการอัปโหลดและเนื้อหาของครีเอเตอร์ควรรวมถึงชื่อวิดีโอ ช่อง เบราว์เซอร์ และข้อผิดพลาดในการประมวลผลที่แสดงบนหน้าอัปโหลด',
  'Sign in for account support' => 'ลงชื่อเข้าใช้เพื่อรับการสนับสนุนบัญชี',
  'Signed in' => 'ลงชื่อเข้าใช้แล้ว',
  'Start uploading' => 'เริ่มการอัปโหลด',
  'Still can’t find an answer?' => 'ยังหาคำตอบไม่ได้ใช่ไหม?',
  'Stored for admins' => 'เก็บไว้สำหรับผู้ดูแลระบบ',
  'Stores language, theme, and interface preferences.' => 'จัดเก็บการตั้งค่าภาษา ธีม และอินเทอร์เฟซ',
  'Studio, playlists, analytics, channels.' => 'สตูดิโอ เพลย์ลิสต์ ข้อมูลวิเคราะห์ ช่อง',
  'Submit a billing or refund message to admin support.' => 'ส่งข้อความเรียกเก็บเงินหรือคืนเงินไปยังฝ่ายสนับสนุนผู้ดูแลระบบ',
  'Submit refund request' => 'ส่งคำขอคืนเงิน',
  'Submit request' => 'ส่งคำขอ',
  'Subscription cancellation' => 'ยกเลิกการสมัครสมาชิก',
  'Support dashboard' => 'แดชบอร์ดการสนับสนุน',
  'System status' => 'สถานะของระบบ',
  'Table' => 'ตาราง',
  'Taxonomies' => 'อนุกรมวิธาน',
  'Technical issue' => 'ปัญหาทางเทคนิค',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'หมายเหตุด้านเทคนิคสำหรับการผสานรวมกับ PlayHub API ปัจจุบันและเวิร์กโฟลว์การอัปโหลด',
  'Tell us more about your question or request...' => 'บอกเราเพิ่มเติมเกี่ยวกับคำถามหรือคำขอของคุณ...',
  'Terms of Use' => 'เงื่อนไขการใช้งาน',
  'The configured' => 'การกำหนดค่าแล้ว',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'หน้านักพัฒนาเชื่อมต่อกับแบ็กเอนด์ Laravel แบบสด: รายการเส้นทาง จำนวนฐานข้อมูล ขีดจำกัดการอัปโหลด และข้อมูลเมตาของแพลตฟอร์มถูกโหลดจาก /api/developers',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'ส่วนหน้าจัดเก็บการตั้งค่าต่างๆ เช่น ภาษาที่เลือก ธีม คิวการเล่น ความคืบหน้าในการรับชม และสถานะอินเทอร์เฟซ เพื่อให้ประสบการณ์การใช้งานยังคงสอดคล้องกันตลอดการนำทางเพจและการโหลดซ้ำ',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'งานประมวลผลจะเข้ารหัสการเรนเดอร์ สร้างภาพขนาดย่อเมื่อจำเป็น เก็บคำบรรยาย และทำเครื่องหมายวิดีโอให้พร้อมเมื่อการประมวลผลเสร็จสิ้น วิดีโอที่กำหนดเวลาไว้ในอนาคตยังคงเป็นส่วนตัวจนกว่าตัวกำหนดเวลาจะเผยแพร่',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'ระบบอัปโหลดได้รับการสนับสนุนจากฐานข้อมูล รองรับหมวดหมู่และภาษาจาก API ประมวลผลวิดีโอที่อัปโหลด จัดเก็บภาพขนาดย่อและคำอธิบายภาพ และเก็บเนื้อหาตามกำหนดการไว้เป็นส่วนตัวจนกว่าจะถึงเวลาเผยแพร่',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'หน้านี้อธิบายวิธีที่ PlayHub ใช้คุกกี้และพื้นที่เก็บข้อมูลเบราว์เซอร์สำหรับเซสชัน ความปลอดภัย การตั้งค่า การเล่น และคุณสมบัติที่ได้รับการตรวจสอบสิทธิ์',
  'Ticket source' => 'แหล่งที่มาของตั๋ว',
  'Top content categories' => 'หมวดหมู่เนื้อหายอดนิยม',
  'Topic' => 'หัวข้อ',
  'Transaction / invoice' => 'ธุรกรรม/ใบแจ้งหนี้',
  'Transaction / invoice ID' => 'รหัสธุรกรรม / ใบแจ้งหนี้',
  'Unable to send message.' => 'ไม่สามารถส่งข้อความได้',
  'Unable to submit refund request.' => 'ไม่สามารถส่งคำขอคืนเงินได้',
  'Understanding admin support tickets' => 'ทำความเข้าใจเกี่ยวกับตั๋วสนับสนุนของผู้ดูแลระบบ',
  'Upload and processing help' => 'ความช่วยเหลือในการอัปโหลดและการประมวลผล',
  'Upload chunks' => 'อัพโหลดเป็นชิ้นๆ',
  'Upload issues' => 'ปัญหาการอัปโหลด',
  'Upload languages' => 'อัปโหลดภาษา',
  'Upload limit' => 'ขีดจำกัดการอัปโหลด',
  'Upload options' => 'ตัวเลือกการอัปโหลด',
  'Upload or processing' => 'อัปโหลดหรือประมวลผล',
  'Upload page' => 'อัพโหลดหน้า',
  'Upload pipeline' => 'อัปโหลดไปป์ไลน์',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'อัปโหลด ดู ติดตาม กลั่นกรอง และสร้างด้วยข้อมูล PlayHub แบบสด',
  'Uploaded videos' => 'วิดีโอที่อัปโหลด',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'วิดีโอที่อัปโหลดจะถูกเข้ารหัสเป็นเวอร์ชันที่สามารถเล่นได้ เวลาในการประมวลผลขึ้นอยู่กับขนาดไฟล์ ระยะเวลา โหลดเซิร์ฟเวอร์ และสถานะคิว หน้าอัปโหลดและสตูดิโอจะแสดงสถานะการประมวลผลจริงจากการบันทึกวิดีโอ',
  'Uploads, scheduling, and processing are available.' => 'การอัปโหลด การกำหนดเวลา และการประมวลผลพร้อมใช้งาน',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'ใช้ /api/videos จุดสิ้นสุดของช่อง และเส้นทางที่ได้รับการตรวจสอบสิทธิ์สำหรับเวิร์กโฟลว์ของผู้สร้าง',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'ใช้การดำเนินการรายงานในตัวสำหรับวิดีโอและความคิดเห็นเพื่อให้ผู้ดูแลระบบได้รับการอ้างอิงเนื้อหาที่ถูกต้อง หน้าแดชบอร์ดผู้ดูแลระบบใช้ข้อมูลฐานข้อมูลสดสำหรับผู้ใช้ เนื้อหา รายงาน การสร้างรายได้ การวิเคราะห์ การสนับสนุน บทบาท และการตั้งค่าระบบ',
  'Use Contact Us' => 'ใช้ติดต่อเรา',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'ใช้ JSON สำหรับคำขอ API ปกติและ FormData สำหรับการอัปโหลดไฟล์ อย่าข้ามการตรวจสอบความถูกต้อง: หมวดหมู่และภาษาเป็นรหัสฐานข้อมูล การมองเห็นจำกัดไว้เฉพาะสาธารณะ ไม่อยู่ในรายการ หรือส่วนตัว และคำอธิบายภาพยอมรับไฟล์ SRT, VTT หรือ TXT',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'ใช้การตั้งค่าเพื่ออัปเดตโปรไฟล์ ความปลอดภัย รหัสผ่าน การจัดส่งแบบสองปัจจัย อุปกรณ์ การตั้งค่า และตัวเลือกการแจ้งเตือน หากคุณไม่สามารถเข้าถึงบัญชีของคุณได้ ให้ใช้ขั้นตอนการเข้าสู่ระบบและแจ้งอีเมลบัญชีแก่ผู้ดูแลเว็บไซต์',
  'Use the contact form' => 'ใช้แบบฟอร์มการติดต่อ',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'ใช้การดำเนินการรายงานกับวิดีโอ ความคิดเห็น และโพสต์ชุมชน เพื่อให้ผู้ดูแลระบบได้รับการอ้างอิงเนื้อหาที่ถูกต้อง',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'ใช้การดำเนินการรายงานกับวิดีโอ ความคิดเห็น และโพสต์ชุมชนเมื่อเนื้อหาอาจละเมิดกฎของแพลตฟอร์ม รายงานเหล่านี้เชื่อมโยงกับบันทึกเนื้อหาจริงและดีกว่าข้อความทั่วไป เนื่องจากผู้ดูแลระบบสามารถตรวจสอบรายการได้ครบถ้วน',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'ใช้ช่องทาง PlayHub ที่เหมาะสมสำหรับความช่วยเหลือด้านบัญชี รายงานเนื้อหา ปัญหาทางเทคนิค และคำขอของผู้ดูแลระบบ',
  'Video categories' => 'หมวดหมู่วิดีโอ',
  'Video for everyone. Built for creators and viewers.' => 'วิดีโอสำหรับทุกคน สร้างจากข้อมูลแพลตฟอร์มจริง',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'ปัญหาในการอัปโหลดวิดีโอ การตั้งเวลา ภาพขนาดย่อ และการประมวลผล',
  'Videos, thumbnails, captions, processing.' => 'วิดีโอ ภาพขนาดย่อ คำบรรยาย การประมวลผล',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'ผู้ดูสามารถเรียกดูหมวดหมู่ ค้นหาวิดีโอ ดูเนื้อหา ติดตามช่อง บันทึกวิดีโอเพื่อดูในภายหลัง แสดงความคิดเห็น รับการแจ้งเตือน และจัดการการตั้งค่าภาษาและการเข้าถึง',
  'Viewing and community help' => 'การรับชมและความช่วยเหลือจากชุมชน',
  'Waiting for backend endpoint inventory.' => 'กำลังรอสินค้าคงคลังปลายทางแบ็กเอนด์',
  'We’re here to help.' => 'เราพร้อมให้ความช่วยเหลือ',
  'What is PlayHub?' => 'PlayHub คืออะไร?',
  'What PlayHub does' => 'PlayHub ทำอะไรบ้าง',
  'Where do contact messages go?' => 'ข้อความติดต่อไปไหน?',
  'Why is my video still processing?' => 'เหตุใดวิดีโอของฉันจึงยังประมวลผลอยู่',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'ใช่. ใช้ฟิลด์วันที่และเวลาของกำหนดการดั้งเดิมในหน้าอัปโหลด แบ็กเอนด์จัดเก็บ schedule_at ประมวลผลวิดีโอ รักษาความเป็นส่วนตัวในขณะที่วันที่อยู่ในอนาคต และเผยแพร่เมื่อตัวกำหนดตารางเวลา Laravel ทำงานหลังจากเวลาที่กำหนด',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'ใช่. ใช้ฟิลด์กำหนดการดั้งเดิมในการอัปโหลด แบ็กเอนด์จะจัดเก็บ schedule_at และเผยแพร่วิดีโอหลังจากประมวลผลเมื่อถึงเวลาที่กำหนด',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'คุณกำลังเรียกดูในฐานะแขก ลงชื่อเข้าใช้เพื่อเข้าถึงเครื่องมือเฉพาะบัญชี',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'คุณต้องรับผิดชอบต่อข้อมูลประจำตัวบัญชีของคุณ กิจกรรมโปรไฟล์ เนื้อหาที่อัปโหลด ความคิดเห็น ข้อความ และการกระทำของผู้สร้างหรือผู้ดูแลระบบใด ๆ ที่ทำจากบัญชีของคุณ ใช้รหัสผ่านที่คาดเดายากและทำให้วิธีการจัดส่งแบบสองปัจจัยเป็นปัจจุบัน',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'คุณสามารถล้างคุกกี้ของเบราว์เซอร์และพื้นที่เก็บข้อมูลในเครื่องได้ในการตั้งค่าเบราว์เซอร์ของคุณ การล้างพื้นที่จัดเก็บข้อมูลที่จำเป็นอาจทำให้คุณออกจากระบบ รีเซ็ตการตั้งค่าภาษา/ธีม ลบสถานะการเล่นในเครื่อง และกำหนดให้คุณต้องเข้าสู่ระบบอีกครั้ง',
  'You receive a response by email.' => 'คุณได้รับการตอบกลับทางอีเมล',
