  'No shorts uploaded yet. Shorts appear here after a vertical video of at most 60 seconds is imported.' => 'ยังไม่มี Shorts วิดีโอแนวตั้งที่นำเข้าและยาวไม่เกิน 60 วินาทีจะแสดงที่นี่',
