  'No shorts uploaded yet. Shorts appear here after a square or vertical video of at most 180 seconds is imported.' => 'ยังไม่มี Shorts วิดีโอแนวตั้งที่นำเข้าและยาวไม่เกิน 60 วินาทีจะแสดงที่นี่',
  'Shorts must be square or vertical videos of at most 180 seconds.' => 'Shorts ต้องเป็นวิดีโอแนวตั้งที่ยาวไม่เกิน 60 วินาที',
